      "type": "number"
    },
    "nbf": {
      "description": "[https://www.rfc-editor.org/rfc/rfc7519#section-4.1.5](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.5)\n",
      "type": "number"
    },
    "aud": {
