Create a Payment > OpenAPI definition #/components/schemas/AEPaymentRequest

{
  "description": "Payment Request Schema\n",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "Data"
  ],
  "properties": {
    "Data": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "ConsentId",
        "Instruction",
        "PaymentPurposeCode",
        "OpenFinanceBilling"
      ],
      "properties": {
        "ConsentId": {
          "$ref": "#/components/schemas/AEPushedAuthorizationRequests.AEConsentId"
        },
        "Instruction": {
          "$ref": "#/components/schemas/AEPaymentInstruction"
        },
        "CurrencyRequest": {
          "$ref": "#/components/schemas/AECurrencyRequest"
        },
        "PersonalIdentifiableInformation": {
          "description": "Personal Identifiable Information, represented in both encoded and decoded form using a `anyOf`, to help implementers readily understand both the structure and serialized form of the property. Schema Objects are provided for both Domestic and International payments.\n\n**Implementations MUST reflect the AEJWEPaymentPII Schema Object structure and the notes provided on** **implementing a JWS and JWE.**\n\n**The decoded form AEPaymentPII is for guidance on content only.**",
          "anyOf": [
            {
              "$ref": "#/components/schemas/AEBankServiceInitiation.AEDomesticPaymentPIIProperties"
            },
            {
              "$ref": "#/components/schemas/AEBankServiceInitiation.AEInternationalPaymentPIIProperties"
            },
            {
              "$ref": "#/components/schemas/AEJWEPaymentPII"
            }
          ]
        },
        "PaymentPurposeCode": {
          "$ref": "#/components/schemas/AEPaymentPurposeCode"
        },
        "DebtorReference": {
          "$ref": "#/components/schemas/AEDebtorReference"
        },
        "CreditorReference": {
          "$ref": "#/components/schemas/AECreditorReference"
        },
        "OpenFinanceBilling": {
          "$ref": "#/components/schemas/AEServiceInitiationOpenFinancePaymentBilling"
        }
      }
    }
  }
}

